// Filter applies the MiauWhereInput filter on the MiauQuery builder.
func (i *MiauWhereInput) Filter(q *MiauQuery) (*MiauQuery, error) {
	if i == nil {
		return q, nil
	}
	p, err := i.P()
	if err != nil {
		if err == ErrEmptyMiauWhereInput {
			return q, nil
		}
		return nil, err
	}
	return q.Where(p), nil
}

